const rows = Array.isArray(fetchPeople.data) ? fetchPeople.data : [];
const people = _.sortBy(rows.filter(r => r && r.email).map(r => ({ id: r.id, name: titleCase(r.name), email: _.toLower(r.email), city: _.get(r, 'address.city', null), company: _.get(r, 'company.name', null) })), 'name');
const byCity = _.countBy(people, p => p.city || 'Unknown');
return { fetched: rows.length, people, byCity, lodashVersion: _.VERSION };
